parameters.jsCode:
// Zet het resultaat klaar voor de drie schrijfnodes.
//
// Dit vervangt de Excel-versie. Daar werd het forum in zes stukken geknipt omdat
// een Excel-cel maximaal 32.767 tekens houdt; Postgres kent die grens niet, dus
// het forum gaat in een keer mee als jsonb.

const bron = $input.first().json;
const trigger = $('When chat message received').first().json;

// Waar de Chat Trigger de velden uit de body neerzet, verschilt per n8n-versie.
// Daarom kijken we op de plekken waar ze kunnen staan.
const uitTrigger = (naam) =>
  trigger[naam] ?? trigger.body?.[naam] ?? trigger.query?.[naam] ?? bron[naam] ?? '';

// De identiteit komt uit het antwoord van Microsoft en niet uit het verzoek:
// wat een browser over zichzelf beweert mag een server niet geloven. Staat de
// node Wie ben jij er nog niet, dan valt dit terug op wat de pagina meestuurt.
let wie = {};
try { wie = $('Wie ben jij').first().json ?? {}; } catch (e) { /* nog niet aangesloten */ }
const gebruiker = trigger.gebruiker ?? trigger.body?.gebruiker ?? {};

// De vraag gaat mee, want zonder die tekst heeft de historie in de zijbalk geen
// kop. De tekst van meegestuurde bestanden gaat bewust NIET mee: die hoort bij
// die ene vraag en heeft in een archief niets te zoeken.
return [{
  json: {
    beurtId:   uitTrigger('beurtId'),
    sessionId: uitTrigger('sessionId'),
    entra_oid: wie.id ?? gebruiker.oid ?? '',
    naam:      wie.displayName ?? gebruiker.naam ?? '',
    email:     wie.mail ?? wie.userPrincipalName ?? gebruiker.email ?? '',
    vraag:     uitTrigger('chatInput'),
    modus:     uitTrigger('modus') || 'grondig',
    output:    String(bron.output ?? ''),
    forum:     bron.forum ?? [],
  },
}];

